(() => {
  // Work map: data from assets/data/projects.json (generated by tools/kml_to_json.py).
  // Colours come from the Google My Maps layers, so the site matches the source map.
  const el = document.getElementById('work-map');
  if (!el || !window.L) return;

  const POLYGON_MIN_ZOOM = 15;   // parcel outlines only make sense at neighbourhood scale
  const filtersEl = document.querySelector('.map-filters');

  const map = L.map(el, {
    preferCanvas: true,
    scrollWheelZoom: false,     // don't hijack page scroll; enabled after the map is clicked
    dragging: !L.Browser.mobile,
    tap: false,
  }).fitBounds([[37.62, 23.3], [38.15, 24.12]]); // Attica, where most of the work is

  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
  }).addTo(map);

  map.on('click', () => map.scrollWheelZoom.enable());
  el.addEventListener('mouseleave', () => map.scrollWheelZoom.disable());

  const cluster = L.markerClusterGroup({
    showCoverageOnHover: false,
    maxClusterRadius: 45,
    disableClusteringAtZoom: POLYGON_MIN_ZOOM,
    iconCreateFunction: (c) => {
      const n = c.getChildCount();
      const size = n < 10 ? 32 : n < 50 ? 40 : 48;
      return L.divIcon({ html: `<span>${n}</span>`, className: 'cluster', iconSize: [size, size] });
    },
  }).addTo(map);
  const parcels = L.layerGroup();

  fetch('assets/data/projects.json')
    .then((r) => r.json())
    .then(({ categories, styles = [], points, polygons = [] }) => {
      const markers = categories.map(() => []);
      const outlines = categories.map(() => []);

      points.forEach(([lat, lng, c]) => {
        markers[c].push(
          L.circleMarker([lat, lng], {
            radius: 6, weight: 2, color: '#fff', fillColor: categories[c].color, fillOpacity: 1,
          }).bindTooltip(categories[c].name, { direction: 'top', offset: [0, -6] })
        );
      });

      polygons.forEach(([c, s, flat]) => {
        const ring = [];
        for (let i = 0; i < flat.length; i += 2) ring.push([flat[i], flat[i + 1]]);
        const st = styles[s] || { color: categories[c].color, fill: 0 };
        outlines[c].push(
          L.polygon(ring, {
            color: st.color, weight: 3, opacity: 1, fillColor: st.color, fillOpacity: st.fill,
          }).bindTooltip(categories[c].name, { sticky: true })
        );
      });

      const active = new Set(categories.map((_, i) => i));
      const render = () => {
        cluster.clearLayers();
        parcels.clearLayers();
        active.forEach((i) => {
          cluster.addLayers(markers[i]);
          outlines[i].forEach((p) => parcels.addLayer(p));
        });
      };
      const syncParcels = () => {
        const show = map.getZoom() >= POLYGON_MIN_ZOOM;
        if (show && !map.hasLayer(parcels)) parcels.addTo(map);
        if (!show && map.hasLayer(parcels)) parcels.remove();
      };
      map.on('zoomend', syncParcels);

      categories.forEach((cat, i) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'chip';
        b.setAttribute('aria-pressed', 'true');
        b.style.setProperty('--c', cat.color);
        b.innerHTML = `<i></i>${cat.name}<span class="mono">${cat.count}</span>`;
        b.addEventListener('click', () => {
          active.has(i) ? active.delete(i) : active.add(i);
          b.setAttribute('aria-pressed', String(active.has(i)));
          render();
        });
        filtersEl.appendChild(b);
      });

      document.querySelectorAll('[data-total]').forEach((n) => { n.textContent = points.length; });
      render();
      syncParcels();
    })
    .catch(() => { el.innerHTML = '<p class="map__error">Ο χάρτης δεν είναι διαθέσιμος αυτή τη στιγμή.</p>'; });
})();
